import inspect
import asyncio
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def iscoroutinefunction(func):
    return inspect.iscoroutinefunction(func)

# Mocking iscoroutinefunction as it's imported conditionally in models.py
# But we can just use Dependant and see if it works.
# Since Dependant is already in the codebase, we can just import it.

def sync_func():
    return "sync"

async def async_func():
    return "async"

def sync_gen():
    yield "sync"

async def async_gen():
    yield "async"

class CallableSync:
    def __call__(self):
        return "sync"

class CallableAsync:
    async def __call__(self):
        return "async"

class CallableSyncGen:
    def __call__(self):
        yield "sync"

class CallableAsyncGen:
    async def __call__(self):
        yield "async"

def test_case(call, expected_coro, expected_gen=False, expected_async_gen=False):
    dep = Dependant(call=call)
    print(f"Testing {call}: coro={dep.is_coroutine_callable == expected_coro}, gen={dep.is_gen_callable == expected_gen}, async_gen={dep.is_async_gen_callable == expected_async_gen}")
    assert dep.is_coroutine_callable == expected_coro
    assert dep.is_gen_callable == expected_gen
    assert dep.is_async_gen_callable == expected_async_gen

# 1. Basic
test_case(sync_func, False)
test_case(async_func, True)
test_case(sync_gen, False, True)
test_case(async_gen, False, False, True)
test_case(CallableSync(), False)
test_case(CallableAsync(), True)
test_case(CallableSyncGen(), False, True)
test_case(CallableAsyncGen(), False, False, True)

# 2. Wrapped
@wraps(sync_func)
def wrap_sync():
    return sync_func()
test_case(wrap_sync, False)

@wraps(async_func)
def wrap_async():
    return asyncio.run(async_func()) # wrap_async is sync, but original is async
# Wait, if wrap_async is sync, it's not a coroutine function.
# But the issue says "if either is async, then it has to be awaited".
# If wrap_async is sync, but wrap_async() returns a coroutine (because it calls async_func), 
# it still needs to be awaited.

@wraps(async_func)
async def wrap_async_async():
    return await async_func()
test_case(wrap_async_async, True)

# Case: Wrapper is sync, original is async
@wraps(async_func)
def wrap_sync_async():
    return async_func()
# wrap_sync_async is NOT a coroutine function, but it returns a coroutine.
# The original code checked iscoroutinefunction(self._unwrapped_call)
# if we unwrap wrap_sync_async, we get async_func, which IS a coroutine function.
test_case(wrap_sync_async, True)

# Case: Wrapper is async, original is sync
@wraps(sync_func)
async def wrap_async_sync():
    return sync_func()
test_case(wrap_async_sync, True)

# 3. Partial
partial_sync = partial(sync_func)
test_case(partial_sync, False)

partial_async = partial(async_func)
test_case(partial_async, True)

# 4. Combined
@wraps(async_func)
def wrap_sync_async():
    return async_func()
partial_wrap_sync_async = partial(wrap_sync_async)
test_case(partial_wrap_sync_async, True)

@wraps(sync_func)
async def wrap_async_sync():
    return sync_func()
partial_wrap_async_sync = partial(wrap_async_sync)
test_case(partial_wrap_async_sync, True)

